const normName = (s: string) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z ]/g, " ").split(/\s+/).filter(Boolean).sort().join(" ");
const normA = (s: string) => { const d = s.replace(/\D/g, ""); return d ? d.padStart(9, "0") : ""; };
const fmtA = (s: string) => { const d = normA(s); return d ? `A${d.slice(0, 3)}-${d.slice(3, 6)}-${d.slice(6)}` : s; };
