    `"a_number": the A-Number / alien registration / file number exactly as written, or "",\n` +
    `"expires": "YYYY-MM-DD" or "", "issued": "YYYY-MM-DD" or "",\n` +
    `"doc_date": main date of a lease, pay stub, bill, school, medical or bank record, "YYYY-MM-DD" or "",\n` +
    `"hearing_date": "YYYY-MM-DD" or "", "hearing_time": "" or like "8:30 AM", "court": court address or "",\n` +
    `"charges": [{"code": INA section exactly as written, "plain": one short plain-English sentence}] or [],\n` +
    `"allegations": the numbered allegations, each under 15 words, or [],\n` +
    `"receipt_number": "", "form": form number like "I-130" or "",\n` +
    `"entry_date": "YYYY-MM-DD" or "", "entry_place": "", "admit_until": "YYYY-MM-DD" or "D/S" or "",\n` +
    `"relation": for family_status, the holder's status like "US citizen" or "green card holder", else "",\n` +
    `"quality": visible photo problems such as "edges cut off", "blurry", "not in English, may need a certified translation", or []}\n` +
    `Type guide: nta = Notice to Appear, Form I-862. hearing_notice = hearing notice from an immigration court (EOIR). entry_record = I-94, visa, or entry stamp. uscis_receipt = Form I-797 notice. presence_proof = lease, bill, pay stub, tax return, school, medical or bank record showing the person was in the US on a date. family_status = a relative's US passport, naturalization certificate, or green card. criminal_record = police report, arrest record, or criminal court paper. Copy names and numbers exactly. Sample documents stamped SPECIMEN are used for demos: read them normally. Do not give legal advice.`;
  const { text, id, model: used } = await near([
    { type: "text", text: prompt },
    { type: "image_url", image_url: { url: `data:${ctype || "image/jpeg"};base64,${b64}` } },
  ], 1500);
  c.lastChat = id;
  c.lastModel = used;
  const d = parseJson(text) || { type: "other", readable: false };
  if (d.type === "not_a_document") return "That doesn't look like a document. Send a photo of one paper or ID, flat on a table.";
  if (d.readable === false) return "I couldn't read that one clearly. Try again in good light, flat on a table, with the whole page in the frame.";
  if (d.type === "criminal_record")
    return "This looks like a police or criminal court paper. I didn't save anything from it. Keep it somewhere safe and show it only to your lawyer.";

